package pilots;
public class FramePerformance{public static void main(String[] args)throws Exception{long begin=System.nanoTime();AnimationClip a=new AnimationClip("/scenes/02-20032.anm"),b=new AnimationClip("/scenes/02-20028.anm");for(int i=0;i<20;i++){if(!a.advance())a.restart();if(!b.advance())b.restart();}long cold=System.nanoTime()-begin;long start=System.nanoTime();for(int i=0;i<2000;i++){if(!a.advance())a.restart();if(!b.advance())b.restart();}System.out.println("Walking: cold40frames_ms="+cold/1000000+" warm4000frames_ms="+(System.nanoTime()-start)/1000000);a.close();b.close();}}
